const qs = [
"entire graph search --repo . --profile full --format agent --top-k 6 --query \"status command JSON output doctor git hooks installed settings worktree\"",
"entire graph search --repo . --profile full --format agent --top-k 6 --query \"Claude Code project hook configuration settings.json settings.local.json\"",
"entire graph search --repo . --profile full --format agent --top-k 6 --query \"settings load explicit worktree root symlink policy\""
];
const out=[];
for (const cmd of qs) out.push(await tools.exec_command({cmd,workdir:"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-checkpoint-metadata-followups",yield_time_ms:30000,max_output_tokens:10000}));
out.forEach((r,i)=>text(`---${i}---\n${r.output}`));

