package claudecode

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"slices"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// Ensure ClaudeCodeAgent implements HookSupport
var (
	_ agent.HookSupport           = (*ClaudeCodeAgent)(nil)
	_ agent.HookConfigLocator     = (*ClaudeCodeAgent)(nil)
	_ agent.HookFreshness         = (*ClaudeCodeAgent)(nil)
	_ agent.PermissionConfigOwner = (*ClaudeCodeAgent)(nil)
)

// Claude Code hook names - these become subcommands under `entire hooks claude-code`
const (
	HookNameSessionStart     = "session-start"
	HookNameSessionEnd       = "session-end"
	HookNameStop             = "stop"
	HookNameUserPromptSubmit = "user-prompt-submit"
	HookNamePreTask          = "pre-task"
	HookNamePostTask         = "post-task"
	HookNamePostTodo         = "post-todo"
	HookNameSubagentStop     = "subagent-stop"
)

// Claude Code tool-name matchers for Entire's PreToolUse/PostToolUse hooks.
//
// The subagent dispatch tool is "Agent" (Claude Code never exposed a tool named
// "Task"), and the "TodoWrite" tool was disabled by default in v2.1.142 in favor
// of the Task* tools. "TaskCreate|TaskUpdate" is a matcher list of exact tool
// names (Claude Code treats a matcher containing only letters/digits/_/-/spaces/
// ,/| as exact strings, not a regex). See:
//   - https://code.claude.com/docs/en/tools-reference.md (Agent, TodoWrite entries)
//   - https://code.claude.com/docs/en/hooks.md (matcher evaluation rules)
//
// Configs written by older CLI versions used the outdated matchers "Task" and
// "TodoWrite", where the hooks silently never fired. Those are not rewritten in
// place on a normal `entire enable`; run with --force to strip and reinstall.
const (
	subagentToolMatcher = "Agent"
	taskToolMatcher     = "TaskCreate|TaskUpdate"
)

// ClaudeSettingsFileName is the settings file used by Claude Code.
// This is Claude-specific and not shared with other agents.
const ClaudeSettingsFileName = "settings.json"

// InstallHooks installs Claude Code hooks in .claude/settings.json.
// If force is true, removes existing Entire hooks before installing.
// Returns the number of hooks installed.
//
// Split into per-phase helpers below; see each helper's doc.
func (c *ClaudeCodeAgent) InstallHooks(ctx context.Context, force bool) (int, error) {
	cfg, err := claudeHookConfig(ctx)
	if err != nil {
		return 0, err
	}

	rawSettings, rawHooks, rawPermissions, err := loadRawClaudeSettingsForInstall(cfg)
	if err != nil {
		return 0, err
	}

	count, staleDropped := installHookEntries(rawHooks, force)

	// Unconditional, like the stale-hook migration in installHookEntries: a
	// plain `entire enable` must drop the retired metadata deny rule, not just
	// --force. See agent.MetadataDenyRule for why it is retired. Removing it is
	// the whole reason a normal enable still touches permissions.
	permissionsChanged, err := agent.RemoveMetadataDenyRule(rawPermissions)
	if err != nil {
		return 0, fmt.Errorf("failed to update permissions in %s: %w", cfg.Path(), err)
	}

	// staleDropped forces a write even when nothing was added: a file holding
	// both a stale and a current hook adds nothing, and returning early here
	// would leave the stale hook on disk.
	if count == 0 && !permissionsChanged && !staleDropped {
		return 0, nil // All hooks and permissions already installed
	}

	if err := writeClaudeSettingsFile(cfg, rawSettings, rawHooks, rawPermissions); err != nil {
		return 0, err
	}

	return count, nil
}

// claudeHookConfig returns .claude/settings.json for the current worktree,
// opened through the worktree's root. Every read, write and removal of that
// file goes through it: the path lives in the working tree, which arrives by
// clone, so a checked-in symlink at `.claude` must not be a directory Entire
// creates and writes through.
func claudeHookConfig(ctx context.Context) (*agent.HookConfigFile, error) {
	repoRoot, err := resolveInstallRepoRoot(ctx)
	if err != nil {
		return nil, err
	}
	return agent.OpenHookConfig(repoRoot, (&ClaudeCodeAgent{}).HookConfigRelPath()) //nolint:wrapcheck // agent.HookConfigFile already names the file in its error
}

func claudeHookConfigForWorktreeRoot(worktreeRoot string) (*agent.HookConfigFile, error) {
	return agent.OpenHookConfig(worktreeRoot, (&ClaudeCodeAgent{}).HookConfigRelPath()) //nolint:wrapcheck // agent.HookConfigFile already names the file in its error
}

// resolveInstallRepoRoot locates the repo root InstallHooks writes under,
// falling back to CWD when not in a git repo (e.g. during tests).
func resolveInstallRepoRoot(ctx context.Context) (string, error) {
	// Use repo root instead of CWD to find .claude directory
	// This ensures hooks are installed correctly when run from a subdirectory
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err == nil {
		return repoRoot, nil
	}
	repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests run outside git repos)
	if err != nil {
		return "", fmt.Errorf("failed to get current directory: %w", err)
	}
	return repoRoot, nil
}

// loadRawClaudeSettingsForInstall reads cfg (if present) and returns
// its top-level fields as raw JSON maps, ready for InstallHooks to mutate.
// rawHooks and rawPermissions are always non-nil (empty maps when absent) so
// callers never need a nil check before indexing them.
func loadRawClaudeSettingsForInstall(cfg *agent.HookConfigFile) (rawSettings, rawHooks, rawPermissions map[string]json.RawMessage, err error) {
	existingData, readErr := cfg.Read()
	if readErr == nil {
		if err := json.Unmarshal(existingData, &rawSettings); err != nil {
			return nil, nil, nil, fmt.Errorf("failed to parse existing settings.json: %w", err)
		}
		// rawHooks preserves unknown hook types (e.g., "Notification")
		if hooksRaw, ok := rawSettings["hooks"]; ok {
			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
				return nil, nil, nil, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
			}
		}
		// rawPermissions preserves unknown permission fields (e.g., "ask")
		if permRaw, ok := rawSettings["permissions"]; ok {
			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
				return nil, nil, nil, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
			}
		}
	} else {
		rawSettings = make(map[string]json.RawMessage)
	}

	if rawHooks == nil {
		rawHooks = make(map[string]json.RawMessage)
	}
	if rawPermissions == nil {
		rawPermissions = make(map[string]json.RawMessage)
	}
	return rawSettings, rawHooks, rawPermissions, nil
}

// installHookEntries mutates rawHooks in place to ensure every Entire hook is
// present, migrating stale entries (from older CLI versions or, when force is
// set, any current Entire hook) first. Returns the number of hooks newly
// added and whether any stale entry was dropped (see the staleDropped comment
// at its InstallHooks call site for why that forces a write on its own).
func installHookEntries(rawHooks map[string]json.RawMessage, force bool) (count int, staleDropped bool) {
	var preToolUse, postToolUse []ClaudeHookMatcher
	parseHookType(rawHooks, "PreToolUse", &preToolUse)
	parseHookType(rawHooks, "PostToolUse", &postToolUse)

	// The "simple" hook types all share one shape: a single Entire command
	// under an empty-string matcher, no tool-use targeting. Handling them
			permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
			if err == nil {
				rawSettings["permissions"] = permJSON
			}
		} else {
			delete(rawSettings, "permissions")
		}
	}

	// Marshal hooks back (preserving unknown hook types)
	if len(rawHooks) > 0 {
		hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
		if err != nil {
			return fmt.Errorf("failed to marshal hooks: %w", err)
		}
		rawSettings["hooks"] = hooksJSON
	} else {
		delete(rawSettings, "hooks")
	}

	// Write back
	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal settings: %w", err)
	}
	return cfg.Write(output, 0o600) //nolint:wrapcheck // agent.HookConfigFile already names the file in its error
}

// loadClaudeSettings reads and parses .claude/settings.json from the repo root.
// A missing file returns the zero settings and no error — that is the answer
// "nothing configured". An unreadable or malformed file returns an error: the
// answer could not be read, which is a different thing.
func loadClaudeSettings(ctx context.Context) (ClaudeSettings, error) {
	cfg, err := claudeHookConfig(ctx)
	if err != nil {
		return ClaudeSettings{}, err
	}
	return loadClaudeSettingsFromConfig(ctx, cfg)
}

func loadClaudeSettingsFromConfig(ctx context.Context, cfg *agent.HookConfigFile) (ClaudeSettings, error) {
	data, err := cfg.Read()
	// No settings file means no hooks, which is an answer; anything else means we
	// could not read the answer.
	if errors.Is(err, os.ErrNotExist) {
		return ClaudeSettings{}, nil
	}
	if err != nil {
		logging.Warn(ctx, "claude-code: failed to read settings file", "path", cfg.Path(), "err", err)
		return ClaudeSettings{}, fmt.Errorf("read %s: %w", cfg.Path(), err)
	}

	var settings ClaudeSettings
	if err := json.Unmarshal(data, &settings); err != nil {
		logging.Warn(ctx, "claude-code: failed to parse settings file", "path", cfg.Path(), "err", err)
		return ClaudeSettings{}, fmt.Errorf("parse %s: %w", cfg.Path(), err)
	}
	return settings, nil
}

// AreHooksInstalled checks if Entire hooks are installed.
//
// A missing settings file is an answer — no hooks — while an unreadable or
// malformed one is an error: "we could not tell" and "there are none" are
// different things to a caller deciding whether hooks can be left alone.
func (c *ClaudeCodeAgent) AreHooksInstalled(ctx context.Context) (bool, error) {
	settings, err := loadClaudeSettings(ctx)
	if err != nil {
		return false, err
	}
	// Check for at least one of our hooks (new, wrapped, or legacy format)
	return hasEntireHook(settings.Hooks.Stop), nil
}

// AreProjectHooksInstalledInWorktree checks an explicit worktree's shared
// .claude/settings.json for Entire hooks. Claude user and local settings are
// outside this portability check because they do not travel with the checkout.
func AreProjectHooksInstalledInWorktree(ctx context.Context, worktreeRoot string) (bool, error) {
	cfg, err := claudeHookConfigForWorktreeRoot(worktreeRoot)
	if err != nil {
		return false, err
	}
	settings, err := loadClaudeSettingsFromConfig(ctx, cfg)
	if err != nil {
		return false, err
	}
	return hasEntireHook(settings.Hooks.Stop), nil
}

// HookConfigState describes how Entire's Claude Code hooks compare to what
// InstallHooks would write today. Aliased to the shared agent-package type so
// `entire status` and `entire doctor` can treat every agent's drift check
// uniformly; the names stay exported here for existing call sites.
//
// For Claude Code, HooksOutdated means Entire hooks are installed but the
// current tool-use matchers no longer carry them (e.g. an older CLI wrote them
// under the now non-firing "Task"/"TodoWrite" matchers).
type HookConfigState = agent.HookConfigState

const (
	// HooksAbsent means Entire hooks are not installed in this repo.
	HooksAbsent = agent.HooksAbsent
	// HooksCurrent means the installed hooks match the current config.
	HooksCurrent = agent.HooksCurrent
	// HooksOutdated means the installed hooks are stale.
	// Fix: `entire enable --force`.
	HooksOutdated = agent.HooksOutdated
)

// CheckHookConfig satisfies agent.HookFreshness by delegating to the
// package-level check, which predates the interface and is still called
// directly by tests.
func (c *ClaudeCodeAgent) CheckHookConfig(ctx context.Context) agent.HookConfigState {
	return CheckHookConfig(ctx)
}

// CheckHookConfig reports whether Entire's Claude Code hooks are absent,
// current, or outdated. It is a read-only diagnostic used by `entire status`
// and `entire doctor`; it never modifies settings. Outdated is detected on the
// positive spec: Entire is installed (Stop hook present) yet one of the current
// tool-use matchers does not carry its Entire hook.
	}
	preferencesFileAbs := ""
	if path, prefErr := ClonePreferencesPath(ctx); prefErr == nil {
		preferencesFileAbs = path
	} else {
		// Log at Debug rather than silently dropping the preferences layer.
		// "Not in a git repo" is a legitimate case (some commands run outside
		// a repo), but a git PATH issue or .git/ permission failure is worth
		// finding via `ENTIRE_LOG_LEVEL=debug` when users report "my picker
		// choices vanished".
		logging.Debug(ctx, "clone preferences path unresolved; skipping preferences layer",
			slog.String("error", prefErr.Error()))
	}

	return loadMergedSettings(ctx, settingsFileAbs, preferencesFileAbs, localSettingsFileAbs)
}

// settingsAbsPaths resolves the base and local settings file paths against the
// repository anchor. Resolution failures are returned rather than converted to
// cwd-relative paths: doing the latter can select a different .entire from a
// subdirectory precisely when Git could not establish which repository owns it.
func settingsAbsPaths(ctx context.Context) (base, local string, err error) {
	// entiredir.PathTo, not paths.AbsPath: both files live under .entire, and
	// entiredir owns the one anchor for that directory. AbsPath's failure mode
	// here was a relative path that then resolved against the process's own
	// directory, which is the thing the anchor exists to prevent.
	base, err = entiredir.PathTo(ctx, EntireSettingsFile)
	if err != nil {
		return "", "", fmt.Errorf("resolve project settings path: %w", err)
	}
	local, err = entiredir.PathTo(ctx, EntireSettingsLocalFile)
	if err != nil {
		return "", "", fmt.Errorf("resolve local settings path: %w", err)
	}
	return base, local, nil
}

// worktreeSettingsPaths resolves the base and local settings file paths under
// an explicit worktree root.
func worktreeSettingsPaths(worktreeRoot string) (base, local string) {
	return filepath.Join(worktreeRoot, EntireSettingsFile), filepath.Join(worktreeRoot, EntireSettingsLocalFile)
}

// LoadForWorktreeRoot is Load for an explicit worktree root instead of the
// process working directory. Code that already holds a repository — a doctor
// repair, a test fixture — must read that repository's settings, not whatever
// the current directory happens to be inside.
func LoadForWorktreeRoot(ctx context.Context, worktreeRoot string) (*EntireSettings, error) {
	return loadForWorktreeRoot(ctx, worktreeRoot)
}

func loadForWorktreeRoot(ctx context.Context, worktreeRoot string) (*EntireSettings, error) {
	return loadForWorktreeRootWithAgentPolicy(ctx, worktreeRoot, true)
}

func loadForWorktreeRootWithAgentPolicy(ctx context.Context, worktreeRoot string, installAgentPolicy bool) (*EntireSettings, error) {
	settingsFileAbs, localSettingsFileAbs := worktreeSettingsPaths(worktreeRoot)
	preferencesFileAbs := ""
	if path, prefErr := clonePreferencesPathForWorktreeRoot(ctx, worktreeRoot); prefErr == nil {
		preferencesFileAbs = path
	} else {
		logging.Debug(ctx, "clone preferences path unresolved; skipping preferences layer",
			slog.String("error", prefErr.Error()))
	}
	return loadMergedSettingsWithAgentPolicy(ctx, settingsFileAbs, preferencesFileAbs, localSettingsFileAbs, installAgentPolicy)
}

func clonePreferencesPathForWorktreeRoot(ctx context.Context, worktreeRoot string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", "-C", worktreeRoot, "rev-parse", "--git-common-dir")
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("resolve git common dir: %w", err)
	}

	commonDir := strings.TrimSpace(string(output))
	if !filepath.IsAbs(commonDir) {
		commonDir = filepath.Join(worktreeRoot, commonDir)
	}
	return filepath.Join(filepath.Clean(commonDir), ClonePreferencesFile), nil
}

// worktreeRootOfSettingsFile recovers the worktree root a settings path was
// built from: settingsAbsPaths joins <root>/.entire/<file>, so the root is two
// levels up. Used only as the KEY the vouched-symlink policy is scoped by, never
// as a base for I/O, so the derived-path rule in CLAUDE.md does not apply -- an
// inconsistent key costs a refused symlink, which is the safe direction.
func worktreeRootOfSettingsFile(settingsFileAbs string) string {
	if settingsFileAbs == "" {
		return ""
	}
	return filepath.Dir(filepath.Dir(settingsFileAbs))
}

func loadMergedSettings(ctx context.Context, settingsFileAbs, preferencesFileAbs, localSettingsFileAbs string) (*EntireSettings, error) {
	return loadMergedSettingsWithAgentPolicy(ctx, settingsFileAbs, preferencesFileAbs, localSettingsFileAbs, true)
}

func loadMergedSettingsWithAgentPolicy(
	ctx context.Context,
	settingsFileAbs, preferencesFileAbs, localSettingsFileAbs string,
	installAgentPolicy bool,
) (*EntireSettings, error) {
	// Load base settings
	settings, err := loadFromFile(settingsFileAbs)
	if err != nil {
		return nil, fmt.Errorf("reading settings file: %w", err)
	}

	var preferences *ClonePreferences
	if preferencesFileAbs != "" {
		preferences, err = loadClonePreferencesFromFile(preferencesFileAbs)
		if err != nil {
			return nil, fmt.Errorf("reading clone preferences file: %w", err)
		}
		applyClonePreferences(settings, preferences)
	}

	// Apply local overrides if they exist — but only from a file that is
	// genuinely local. See localLayerTrackedReason.
	localData, err := readConfined(localSettingsFileAbs)
	if err != nil {
		if !errors.Is(err, fs.ErrNotExist) {
			return nil, fmt.Errorf("reading local settings file: %w", err)
		}
		// Local file doesn't exist, continue without overrides
	} else if classifyLocalSettings(ctx, localSettingsFileAbs) == localTracked {
		// Dropped only on PROOF that the file is tracked. Discarding every
		// local setting because a repository could not be read would be a
		// worse failure than the one being guarded against — the exec-bearing
		// OPF command applies the stricter policy for itself.
		settings.localLayerRejection = localLayerTrackedReason
		localData = nil
	} else if err := mergeJSON(settings, localData); err != nil {
		return nil, fmt.Errorf("merging local settings: %w", err)
	}

	// openai_privacy_filter.command is executed, so it is honored only from a
	// local file positively verified as this developer's own. external_agents
	// grants execution of every entire-agent-* binary on $PATH, so it gets the
	// same gate. Agent instruction fields (investigate.always_prompt, review
	// prompts) are appended verbatim to prompts of agents spawned with
	// approval checks disabled, so they get the same provenance requirement,
	// with clone-local preferences as an additional trusted layer.
	enforceOPFCommandTrust(ctx, settings, localSettingsFileAbs, localData)
	enforceExternalAgentsTrust(ctx, settings, localSettingsFileAbs, localData)
	enforceAgentPromptTrust(ctx, settings, localSettingsFileAbs, localData, preferences)
	// allow_symlinked_agent_dirs decides where Entire writes an agent's hook
	// config, so it gets the same gate, and then installs the surviving set as
	// the process-wide policy.
	enforceSymlinkedAgentDirsTrust(ctx, settings, localSettingsFileAbs, localData)
	if installAgentPolicy {
		applyVouchedAgentDirs(settings, worktreeRootOfSettingsFile(settingsFileAbs))
	}

	// Re-validate after merge. Individual files are validated by loadFromFile,
	// but mergeJSON patches fields independently and can produce combinations
	// (e.g. model without provider when the local override sets only a model
	// on top of a base with no provider) that neither file alone contained.
	if err := settings.SummaryGeneration.Validate(); err != nil {
		return nil, fmt.Errorf("merged settings invalid: %w", err)
	}

	if err := validateScannerSettings(settings); err != nil {
		return nil, fmt.Errorf("merged settings invalid: %w", err)
	}

	return settings, nil
}

// LoadFromFile loads settings from a specific file path without merging local overrides.
// Returns default settings if the file doesn't exist.
// Use this when you need to display individual settings files separately.
func LoadFromFile(filePath string) (*EntireSettings, error) {
	return loadFromFile(filePath)
}

// LoadProjectRaw reads .entire/settings.json as a generic JSON object so
// callers can inspect or mutate individual keys without losing unrelated
// fields to round-trip decoding.
//
// Returns:
	if v, ok := raw["phone"]; ok {
		var b bool
		if err := json.Unmarshal(v, &b); err != nil {
			return fmt.Errorf("parsing pii.phone: %w", err)
		}
		dst.Phone = &b
	}
	if v, ok := raw["address"]; ok {
		var b bool
		if err := json.Unmarshal(v, &b); err != nil {
			return fmt.Errorf("parsing pii.address: %w", err)
		}
		dst.Address = &b
	}
	if v, ok := raw["custom_patterns"]; ok {
		if err := mergeStringMap(&dst.CustomPatterns, v, "pii.custom_patterns"); err != nil {
			return err
		}
	}
	return nil
}

// mergeStringMap unmarshals raw into a string map and merges it into dst,
// adopting the parsed map wholesale when dst is nil. field names the setting
// in parse errors.
func mergeStringMap(dst *map[string]string, raw json.RawMessage, field string) error {
	var m map[string]string
	if err := json.Unmarshal(raw, &m); err != nil {
		return fmt.Errorf("parsing %s: %w", field, err)
	}
	if *dst == nil {
		*dst = m
		return nil
	}
	for k, v := range m {
		(*dst)[k] = v
	}
	return nil
}

// IsSetUp returns true if Entire has been set up in the current repository.
// This checks if .entire/settings.json exists.
// Use this to avoid creating files/directories in repos where Entire was never enabled.
func IsSetUp(ctx context.Context) bool {
	return entireFileExists(ctx, SettingsName)
}

// FilesPresent reports whether each settings file exists, keeping an access
// failure distinct from absence. IsSetUp and IsSetUpLocal collapse both into
// false, which is right for a gate but wrong for `entire status`, whose whole
// job is to say why it cannot see something.
func FilesPresent(ctx context.Context) (project, local bool, err error) {
	root, err := entiredir.OpenForRead(ctx)
	return filesPresent(root, err)
}

// FilesPresentForWorktreeRoot is FilesPresent for an explicit worktree root.
func FilesPresentForWorktreeRoot(worktreeRoot string) (project, local bool, err error) {
	root, err := entiredir.OpenAtForRead(worktreeRoot)
	return filesPresent(root, err)
}

func filesPresent(root *os.Root, openErr error) (project, local bool, err error) {
	err = openErr
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return false, false, nil
		}
		return false, false, fmt.Errorf("cannot access %s: %w", paths.EntireDir, err)
	}
	project, err = fileExists(root, SettingsName)
	if err != nil {
		return false, false, fmt.Errorf("cannot access project settings file: %w", err)
	}
	local, err = fileExists(root, SettingsLocalName)
	if err != nil {
		return false, false, fmt.Errorf("cannot access local settings file: %w", err)
	}
	return project, local, nil
}

func fileExists(root *os.Root, name string) (bool, error) {
	if _, err := root.Lstat(name); err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return false, nil
		}
		return false, err //nolint:wrapcheck // caller names the file
	}
	return true, nil
}

// IsSetUpLocal returns true if .entire/settings.local.json exists. Callers that
// pick a write target need the two scopes separately, which IsSetUpAny folds
// together.
func IsSetUpLocal(ctx context.Context) bool {
	return entireFileExists(ctx, SettingsLocalName)
}

// IsSetUpAny returns true if Entire has been set up in the current repository,
// checking both .entire/settings.json and .entire/settings.local.json.
// Use this to detect any prior setup, even if only local settings exist.
func IsSetUpAny(ctx context.Context) bool {
	return IsSetUp(ctx) || IsSetUpLocal(ctx)
}

// entireFileExists reports whether name exists directly under .entire. Lstat,
// not Stat: a settings file that is a dangling symlink still counts as "set up"
// here, exactly as it did before, and the root refuses to follow one out of
// .entire regardless.
func entireFileExists(ctx context.Context, name string) bool {
	root, err := entiredir.OpenForRead(ctx)
	if err != nil {
		return false
	}
	_, err = root.Lstat(name)
	return err == nil
}

// IsSetUpAndEnabled returns true if Entire is both set up and enabled.
// "Set up" spans either scope — .entire/settings.json OR
// .entire/settings.local.json — so it must check IsSetUpAny, not IsSetUp.
// `entire enable --local` writes only settings.local.json and never creates the
// base file; gating on the base file alone would treat such a local-only repo
// as inactive and make every hook a silent no-op, dropping all checkpoint
// capture for that documented workflow. The IsSetUpAny guard is still required
// so a never-enabled repo (no settings file in any scope) is not treated as
// enabled by Load's default Enabled: true. Any settings read error is treated
// as disabled (fail closed).
// Use this for hooks that should be no-ops when Entire is not active.
func IsSetUpAndEnabled(ctx context.Context) bool {
	if !IsSetUpAny(ctx) {
		return false
	}
	s, err := Load(ctx)
	if err != nil {
		return false
	}
	return s.Enabled
}

// IsSetUpAndEnabledForWorktreeRoot is a read-only IsSetUpAndEnabled for an
// explicit worktree root. It does not install that worktree's agent-directory
// policy into the process.
func IsSetUpAndEnabledForWorktreeRoot(ctx context.Context, worktreeRoot string) bool {
	project, local, err := FilesPresentForWorktreeRoot(worktreeRoot)
	if err != nil || (!project && !local) {
		return false
	}
	// This is an inspection of another worktree. Loading its effective settings
	// must not replace the current worktree's process-wide agent-directory policy.
	s, err := loadForWorktreeRootWithAgentPolicy(ctx, worktreeRoot, false)
	if err != nil {
		return false
	}
	return s.Enabled
}

// IsFilteredFetchesEnabled checks if filtered fetches should be used.
// When enabled, filtered fetches always resolve remote names to URLs first so
// git does not persist promisor settings onto named remotes in local config.
// Returns false by default.
func IsFilteredFetchesEnabled(ctx context.Context) bool {
	s, err := Load(ctx)
	if err != nil {
		return false
	}

