func codexHooksStatusFromIssue(issue *codexHookIssue) *codexHooksStatusJSON {
	if issue == nil {
		return nil
	}
	return &codexHooksStatusJSON{
		State:            issue.State,
		WorktreePath:     issue.WorktreePath,
		DiscoveredPath:   issue.DiscoveredPath,
