  80	func parseSiblingWorktrees(porcelain []byte, currentRoot string) []string {
  81		var worktrees []string
  82		var path string
  83		prunable := false
  84		for _, field := range bytes.Split(porcelain, []byte{0}) {
  85			line := string(field)
  86			switch {
  87			case line == "":
  88				if path != "" && !prunable && normalizeWorktreePath(path) != currentRoot {
  89					worktrees = append(worktrees, path)
  90				}
  91				path = ""
  92				prunable = false
  93			case strings.HasPrefix(line, "worktree "):
  94				path = strings.TrimPrefix(line, "worktree ")
  95			case line == "prunable" || strings.HasPrefix(line, "prunable "):
  96				prunable = true
  97			}
  98		}
  99		return worktrees
 100	}
