  67	func siblingWorktrees(ctx context.Context, currentRoot string) []string {
  68		ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
  69		defer cancel()
  70	
  71		cmd := exec.CommandContext(ctx, "git", "worktree", "list", "--porcelain", "-z")
  72		cmd.Dir = currentRoot
  73		output, err := cmd.Output()
  74		if err != nil {
  75			return nil
  76		}
